UPDATE courses SET
    course_description = '<p>The course is designed for education professionals who aspire to accelerate their leadership path within educational institutions.<br/></p><p>This coursework-based program equips you with advanced knowledge in management, leadership, and strategic decision-making, tailored specifically for the educational context. Graduates will be able to effectively manage resources, foster innovation, and lead educational teams to deliver exceptional outcomes, positioning themselves as influential leaders in Australia’s evolving educational landscape.<br/></p><p>This course has been accredited by ECU as an <a href="https://www.aqf.edu.au/framework/aqf-qualifications">AQF Level 9 Masters Degree (Coursework)<i></i></a> Award.</p><p>ECU admission and English language requirements apply.</p><p>See <a href="#courseEntryDom">Course Entry</a> for further information.</p><p><a href="https://www.ecu.edu.au/study/shared-content/admission-information-sets/Whole-of-Institution-Information-Set.pdf">ECU admission profile</a></p><p>Domestic fee paying - estimated 1st year indicative fee <strong>AUD $31,100</strong></p><p>See <a href="#feesScholarshipsDom">Fees and Scholarships</a> for further information.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 31100,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
