UPDATE courses SET
    course_description = '<p>This Master of Cyber Security degree is designed to address the needs of industry for cyber security professionals within government, law enforcement and industry.<br/></p><p>The course engages with, and provides a pathway for, information technology professionals seeking to commence or further progress their careers in the cyber security domain. It is also relevant to those seeking to enter the IT profession who have no previous experience in the cyber discipline.<br/></p><p>This course has been accredited by ECU as an <a href="https://www.aqf.edu.au/framework/aqf-qualifications">AQF Level 9 Masters Degree (Coursework)<i></i></a> Award.</p><p>ECU admission and English language requirements apply.</p><p>See <a href="#courseEntryDom">Course Entry</a> for further information.</p><p><a href="https://www.ecu.edu.au/study/shared-content/admission-information-sets/Whole-of-Institution-Information-Set.pdf">ECU admission profile</a></p><p>Domestic fee paying - estimated 1st year indicative fee <strong>AUD $32,550</strong></p><p>See <a href="#feesScholarshipsDom">Fees and Scholarships</a> for further information.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 65100,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
