UPDATE courses SET
    course_description = '<p>This course provides students with skills and experience in environmental science, focusing on project management, occupational health and safety, sustainability, monitoring and reporting.<br/></p><p>It provides work experience in relevant organisations within the industry, allowing students to gain an understanding of the management of environmental projects. It also focuses on skills for the environmental, engineering, and sustainability professions and offers flexible study options through on-campus and off-campus study.<br/></p><p>This course has been accredited by ECU as an <a href="https://www.aqf.edu.au/framework/aqf-qualifications">AQF Level 9 Masters Degree (Coursework)<i></i></a> Award.</p><p>ECU admission and English language requirements apply.</p><p>See <a href="#courseEntryDom">Course Entry</a> for further information.</p><p><a href="https://www.ecu.edu.au/study/shared-content/admission-information-sets/Whole-of-Institution-Information-Set.pdf">ECU admission profile</a></p><p>Domestic fee paying - estimated 1st year indicative fee <strong>AUD $28,450</strong></p><p>See <a href="#feesScholarshipsDom">Fees and Scholarships</a> for further information.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 56900,
