UPDATE courses SET
    course_description = '<p>If you’re a practising midwife and want to apply a specialised body of knowledge to your practice, this course will help you advance your career by developing your leadership and training skills.<br/></p><p>ECU admission and English language requirements apply.</p><p>See <a href="#courseEntryDom">Course Entry</a> for further information.</p><p><a href="https://www.ecu.edu.au/study/shared-content/admission-information-sets/Whole-of-Institution-Information-Set.pdf">ECU admission profile</a></p><p>Domestic fee paying - estimated 1st year indicative fee <strong>AUD $17,700</strong></p><p>See <a href="#feesScholarshipsDom">Fees and Scholarships</a> for further information.</p><p>2 years full-time or part-time equivalent</p><p>See <a href="#courseDetailsDom">Course Details</a> for further information.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 35400,
    onshore_tuition_fee = NULL,
